<script setup>
import FilterBar from '../../shared/components/FilterBar.vue';

import { onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue';
import { useDigitalRuntime } from './digital-runtime.js';
import { money,time,stateNames,providerNames,canReceipt,canVerify } from './digital-model.js';
import { saleStatuses,canReadReceipt,canRequestReprint } from '../sales/sales-model.js';
import DigitalReceipt from './DigitalReceipt.vue';
import './digital.css';
const props=defineProps({sales:{type:Object,required:true}}),emit=defineEmits(['stockReceipt','stockDetails','stockReprint']),vm=useDigitalRuntime(),filters=reactive({q:'',kind:'all',from:'',to:''}),rows=ref([]),loading=ref(false),meta=reactive({current_page:1,last_page:1,total:0}),keys=new Map();let reader,timer,revision=0;
async function load(page=1){reader?.abort();reader=new AbortController();const expected=++revision;loading.value=true;try{const response=await vm.api.history({...filters,page},reader.signal);if(expected!==revision)return;rows.value=response.data;Object.assign(meta,response.meta);}catch(error){if(error.name!=='AbortError')vm.state.error=await vm.failure(error);}finally{if(expected===revision)loading.value=false;}}
async function verify(order){if(!keys.has(order.id))keys.set(order.id,vm.key());const result=await vm.execute({version:order.version},keys.get(order.id),(payload,signal)=>vm.api.action(order.id,'verify',payload,signal),'تم التحقق من الطلب نفسه.');if(result)await load(meta.current_page);}
watch(filters,()=>{clearTimeout(timer);timer=setTimeout(()=>load(),250);});onMounted(()=>load());onBeforeUnmount(()=>{reader?.abort();clearTimeout(timer);revision++;rows.value=[];});
</script>
<template><section class="pos-phone-operations"><h2>العمليات</h2><p v-if="vm.state.error" class="notice warn" role="alert">{{vm.state.error}}</p><FilterBar class="toolbar"><input v-model="filters.q" type="search" placeholder="بحث في العمليات" aria-label="بحث في العمليات"><select v-model="filters.kind" aria-label="نوع الخدمة"><option value="all">الكل</option><option value="card">بطاقات</option><option value="topup">Topup</option></select><input v-model="filters.from" type="date" aria-label="من تاريخ"><input v-model="filters.to" type="date" aria-label="إلى تاريخ"><button class="btn small" :disabled="loading" @click="load(meta.current_page)">تحديث</button></FilterBar><article v-for="item in rows" :key="`${item.kind}:${item.record.id}`" class="card"><div><strong>{{item.record.product_name}}</strong><span class="badge neutral">{{item.kind==='stock'?saleStatuses[item.record.status]:stateNames[item.record.status]}}</span></div><small>{{item.kind==='stock'?item.record.provider_name:providerNames[item.record.provider]}} · {{time(item.record.issued_at||item.record.created_at)}} · {{item.record.request_id||item.record.id}}</small><p v-if="item.kind==='digital'&&item.record.receipt_missing" class="notice warn">أكدت الشركة الشراء، لكن رمز البطاقة لم يصل. راجع الوكيل دون إعادة شراء.</p><p v-if="item.record.failure_reason||item.record.message" class="caption">{{item.record.failure_reason||item.record.message}}</p><div><b>{{money(item.kind==='stock'?item.record.retail_total:item.record.retail)}} د.ع</b><template v-if="item.kind==='stock'"><button v-if="canReadReceipt(item.record,sales.identity.value,sales.can)" class="btn small" @click="emit('stockReceipt',item.record)">عرض الوصل</button><button v-else class="btn small" @click="emit('stockDetails',item.record)">عرض التفاصيل</button><button v-if="canRequestReprint(item.record,sales.identity.value,sales.can)" class="btn small" @click="emit('stockReprint',item.record)">إعادة طباعة</button></template><template v-else><button v-if="canReceipt(item.record,vm.identity.value,vm.can)" class="btn small" @click="vm.openReceipt(item.record)">عرض الوصل</button><button v-if="canVerify(item.record,vm.identity.value,vm.can)" class="btn small" :disabled="vm.state.busy" @click="verify(item.record)">تحقق من النتيجة</button></template></div><small v-if="item.kind==='digital'&&item.record.reservation_active&&item.record.verification_supported===false">مسار التحقق غير وارد في وثيقة المزود الحالية؛ راجع مرجع الطلب لدى الشركة.</small></article><p v-if="!rows.length" class="empty">{{loading?'جارٍ التحميل…':'لا توجد عمليات مطابقة'}}</p><div class="sales-pagination"><button class="btn small" :disabled="loading||meta.current_page<=1" @click="load(meta.current_page-1)">السابق</button><span>{{meta.current_page}} / {{meta.last_page}} · {{meta.total}}</span><button class="btn small" :disabled="loading||meta.current_page>=meta.last_page" @click="load(meta.current_page+1)">التالي</button></div><DigitalReceipt v-if="vm.receipt.value" :vm="vm" :receipt="vm.receipt.value" @close="vm.clearReceipt()"/></section></template>
